import { matchesGlob } from "node:path";

export type File = { filename: string; additions: number; deletions: number };
export type Effort = "low" | "medium" | "high";
export type RiskTier = "low" | "med" | "high";

const MODEL = "claude-opus-5-5";
const LARGE_PR_LINES = 400;
const GENERATED = /(^|\/)(package-lock\.json|uv\.lock|yarn\.lock)$|_pb2(_grpc)?\.pyi?$/;
const DOCS = /\.(md|mdx|txt)$|(^|\/)docs\//;
const TESTS = /(^|\/)(tests?|e2e|__tests__)\/|\.(test|spec)\.[jt]sx?$|(^|\/)test_[^/]+\.py$/;
const DEPS = /(^|\/)(package\.json|pyproject\.toml|requirements[^/]*\.txt)$/;

export const reviewRoute = (files: File[]) => {
  const counted = files.filter((f) => !GENERATED.test(f.filename));
  const lines = counted.reduce((sum, f) => sum + f.additions + f.deletions, 0);
  const all = (pattern: RegExp) => counted.every((f) => pattern.test(f.filename));
  if (all(DOCS) || all(TESTS) || all(DEPS)) return { model: MODEL, effort: "low" as Effort, reason: "docs-, test- or dependency-only" };
  if (lines > LARGE_PR_LINES) return { model: MODEL, effort: "high" as Effort, reason: `${lines} changed lines` };
  return { model: MODEL, effort: "medium" as Effort, reason: `${lines} changed lines` };
};

const RISK = {
  high: { paths: ["cloud/rhinoCloud/rhinoCore/migrations/**", "cloud/rhinoCloud/rhinoCore/permissions.py", ".github/workflows/**"], reason: "migrations, permissions or CI" },
  low: { paths: ["**/*.md", "**/*.stories.tsx", "**/tests/**", "**/*.test.tsx"], reason: "docs or tests only" },
};
const RAISE_ABOVE_LINES = 800;
const ORDER: RiskTier[] = ["low", "med", "high"];
const matches = (path: string, globs: string[]) => globs.some((g) => matchesGlob(path, g));

export const riskFor = (files: File[]) => {
  const reasons: string[] = [];
  let tier: RiskTier = files.every((f) => matches(f.filename, RISK.low.paths)) ? "low" : "med";
  const risky = files.filter((f) => matches(f.filename, RISK.high.paths));
  if (risky.length > 0) {
    tier = "high";
    reasons.push(`${risky.length} file(s): ${RISK.high.reason}`);
  }
  const lines = files.reduce((sum, f) => sum + f.additions + f.deletions, 0);
  if (lines > RAISE_ABOVE_LINES && tier !== "high") {
    tier = ORDER[ORDER.indexOf(tier) + 1];
    reasons.push(`${lines} changed lines`);
  }
  return { tier, reasons: reasons.length > 0 ? reasons : [tier === "low" ? RISK.low.reason : "no high-risk paths"] };
};

export const reviewMode = (risk: RiskTier, changedLines: number, asked?: "deep") => {
  if (asked === "deep") return { mode: "deep", reason: "asked with @byte-review deep" };
  if (risk === "high") return { mode: "deep", reason: "risk:high" };
  if (changedLines > RAISE_ABOVE_LINES) return { mode: "deep", reason: `${changedLines} changed lines` };
  return { mode: "standard", reason: "single review session" };
};
